#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
/// Why a primitive could not run.
pub enum DspError {
    #[error("input too short: need at least {need} samples, got {got}")]
    /// Fewer samples than the operation needs.
    TooShort {
        /// Minimum number of samples required.
        need: usize,
        /// Number of samples given.
        got: usize,
    },
    #[error("invalid parameter: {0}")]
    /// A parameter is out of range or inconsistent.
    InvalidParam(String),
}

/// Smallest `n >= target` whose prime factors are all in {2, 3, 5}.
/// rustfft handles any length; "5-smooth" lengths are simply the fastest.
pub fn next_smooth(target: usize) -> usize {
    let mut n = target.max(1);
    loop {
        let mut m = n;
        for p in [2usize, 3, 5] {
            while m.is_multiple_of(p) {
                m /= p;
            }
        }
        if m == 1 {
            return n;
        }
        n += 1;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn smooth_lengths() {
        assert_eq!(next_smooth(1), 1);
        assert_eq!(next_smooth(7), 8);
        assert_eq!(next_smooth(1000), 1000);
        assert_eq!(next_smooth(1001), 1024);
        assert_eq!(next_smooth(4001), 4050);
    }
}
